package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                               // PIC 99 len=2 = 0
var WsCount int64 = 0                              // PIC 99 len=2 = 0
var WsBalEd string = ""                            // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec
var schedLines []string
var schedIndex int

func parseImplied(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(t)
	if err != nil {
		n, err2 := strconv.ParseInt(t, 10, 64)
		if err2 != nil {
			fmt.Fprintf(os.Stderr, "parse implied %q: %v\n", s, err)
			os.Exit(1)
		}
		d = decimal.NewFromInt(n)
	}
	return d.Shift(-scale)
}

func storeIntPic(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= 0 {
		return v % mod
	}
	abs := -v
	r := abs % mod
	return -r
}

func storePic9_8V99(d decimal.Decimal) decimal.Decimal {
	totalDigits := int32(10)
	fracDigits := int32(2)
	pow := decimal.NewFromInt(1).Shift(totalDigits) // 10^10
	scaled := d.Shift(fracDigits)
	scaled = scaled.Truncate(0)
	if scaled.IsNegative() {
		abs := scaled.Abs()
		if abs.Cmp(pow) >= 0 {
			abs = abs.Mod(pow)
			scaled = abs.Neg()
		}
	} else {
		if scaled.Cmp(pow) >= 0 {
			scaled = scaled.Mod(pow)
		}
	}
	return scaled.Shift(-fracDigits)
}

func formatWsBalEd(d decimal.Decimal) string {
	isNeg := d.IsNegative()
	absD := d.Abs()
	scaled := absD.Shift(2).Truncate(0)
	intPartDec := scaled.Div(decimal.NewFromInt(100)).Truncate(0)
	fracPartDec := scaled.Sub(intPartDec.Mul(decimal.NewFromInt(100)))
	intPart := intPartDec.IntPart()
	fracPart := fracPartDec.IntPart()
	// keep low 8 digits if overflow (already done by store, but keep for safety)
	intPart = intPart % 100000000
	if intPart < 0 {
		intPart = -intPart
	}
	intStr := fmt.Sprintf("%08d", intPart)
	fracStr := fmt.Sprintf("%02d", fracPart)

	out := make([]byte, 13)
	// map integer digits to picture positions
	picIdxForDigit := []int{0, 1, 3, 4, 5, 7, 8, 9}
	for i, picIdx := range picIdxForDigit {
		out[picIdx] = intStr[i]
	}
	out[2] = ','
	out[6] = ','
	out[10] = '.'
	out[11] = fracStr[0]
	out[12] = fracStr[1]

	zIndices := map[int]bool{0: true, 1: true, 3: true, 4: true, 5: true, 7: true, 8: true}

	// find first non-zero in intStr
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		for _, picIdx := range picIdxForDigit {
			if zIndices[picIdx] {
				out[picIdx] = ' '
			}
		}
		out[2] = ' '
		out[6] = ' '
	} else {
		for i, picIdx := range picIdxForDigit {
			if i < firstNonZero && zIndices[picIdx] {
				out[picIdx] = ' '
			}
		}
		if out[0] == ' ' && out[1] == ' ' {
			out[2] = ' '
		}
		if out[0] == ' ' && out[1] == ' ' && out[3] == ' ' && out[4] == ' ' && out[5] == ' ' {
			out[6] = ' '
		}
	}
	res := string(out)
	if isNeg {
		// unsigned field - just prefix minus if needed (not expected)
		// replace first space before digit with '-'
		for i := 0; i < len(res); i++ {
			if res[i] != ' ' {
				if i > 0 {
					b := []byte(res)
					b[i-1] = '-'
					res = string(b)
				}
				break
			}
		}
		if res[0] != '-' && res[0] == ' ' {
			b := []byte(res)
			b[0] = '-'
			res = string(b)
		}
	}
	return res
}

func formatPIC99(v int64) string {
	return fmt.Sprintf("%02d", v)
}

func READPARA() {
	if schedIndex >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedIndex]
	schedIndex++
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	curRec.ScAcct = line[0:4]
	curRec.ScPrin = parseImplied(line[4:11], 2)
	curRec.ScRate = parseImplied(line[11:15], 2)
	yStr := strings.TrimSpace(line[15:16])
	if yStr == "" {
		curRec.ScYears = 0
	} else {
		y, err := strconv.ParseInt(yStr, 10, 64)
		if err != nil {
			fmt.Fprintf(os.Stderr, "parse years %q: %v\n", yStr, err)
			os.Exit(1)
		}
		curRec.ScYears = storeIntPic(y, 1)
	}
}

func PROCESSPARA() {
	WsBal = storePic9_8V99(curRec.ScPrin)
	WsYear = storeIntPic(1, 2)
	for {
		if WsYear > curRec.ScYears {
			break
		}
		rateDiv := curRec.ScRate.Shift(-2)
		onePlus := decimal.NewFromInt(1).Add(rateDiv)
		raw := WsBal.Mul(onePlus)
		rounded := raw.Round(2)
		WsBal = storePic9_8V99(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		yearStr := formatPIC99(WsYear)
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, yearStr, WsBalEd)
		WsYear = storeIntPic(WsYear+1, 2)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount = storeIntPic(WsCount+1, 2)
	READPARA()
}

func MAINPARA() {
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	countStr := formatPIC99(WsCount)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			schedLines = []string{}
		} else {
			fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
			os.Exit(1)
		}
	} else {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			schedLines = append(schedLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
			os.Exit(1)
		}
	}
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = ""
	MAINPARA()
}
